const TYPES=['LeetCode','AI coding','Math / theory','Research / interview','Review','Rest'];const STATUS={'not-started':'Not started','in-progress':'In progress','done':'Completed','review':'Needs review','rest':'Rest'};const CLASS={'LeetCode':'leetcode','AI coding':'ai','Math / theory':'math','Research / interview':'research','Review':'review','Rest':'rest'};const KEY='ai-interview-academy-v2-demo';const $=id=>document.getElementById(id);const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const safeUrl=u=>/^https:\/\//.test(u)?esc(u):'#';const fmt=(d,opts={month:'short',day:'numeric',year:'numeric'})=>new Intl.DateTimeFormat('en-GB',{...opts,timeZone:'UTC'}).format(new Date(d+'T12:00:00Z'));const dateKey=()=>new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Sofia',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());const clamp=(n,a,b)=>Math.min(b,Math.max(a,n));let data={};let theme='light';let storageOK=true;try{theme=localStorage.getItem(KEY+'-theme')||'light'}catch(e){storageOK=false}let selected=clamp(DAYS.findIndex(d=>d.date>=dateKey())<0?364:DAYS.findIndex(d=>d.date>=dateKey()),0,364);let page='today',pageNum=0;let timerId=null,deadline=0,timerIndex=null;let toastId;const STUDY=DAYS.filter(d=>d.minutes>0);const entry=d=>data[d.date]||{};const status=d=>d.minutes===0?'rest':entry(d).status||'not-started';const completed=ds=>ds.filter(d=>status(d)==='done').length;const pct=(n,total)=>total?Math.round(n/total*100):0;const seconds=d=>clamp(Number(entry(d).seconds)||0,0,d.minutes*60);const chip=d=>`<span class="chip ${CLASS[d.type]}">${esc(d.type)}</span>`;const bar=(n,t)=>`<div class="progress-track" role="progressbar" aria-valuenow="${pct(n,t)}" aria-valuemin="0" aria-valuemax="100"><div class="progress-fill" style="width:${pct(n,t)}%"></div></div>`;
function save(){try{localStorage.setItem(KEY+'-theme',theme);if(mode==='demo')localStorage.setItem(KEY,JSON.stringify({entries:data,theme}));if(mode==='cloud')persistQueue();storageOK=true}catch(e){storageOK=false}}function notify(s){$('toast').textContent=s;$('toast').classList.add('show');clearTimeout(toastId);toastId=setTimeout(()=>$('toast').classList.remove('show'),2400)}function update(d,patch){if(mode==='locked')return;data[d.date]={...entry(d),...patch};if(mode==='cloud')queuePatch(d.date,patch);save()}function go(p){page=p;document.querySelectorAll('.page').forEach(el=>el.classList.toggle('active',el.id==='page-'+p));document.querySelectorAll('.navbtn').forEach(el=>{el.classList.toggle('active',el.dataset.page===p);if(el.dataset.page===p)el.setAttribute('aria-current','page');else el.removeAttribute('aria-current')});$('crumb').textContent={today:'Daily dashboard',program:'Full program',roadmap:'Roadmap',resources:'Resource library',progress:'My progress',partners:'Study together'}[p];render();window.scrollTo({top:0,behavior:'instant'})}function selectDay(i){if(i<0||i>=DAYS.length)return;if(i!==selected)pauseTimer();selected=i;go('today')}function today(){const i=DAYS.findIndex(d=>d.date>=dateKey());selectDay(i<0?364:i)}function chooseWeek(w){$('weekFilter').value=String(w);$('search').value='';$('typeFilter').value='';$('statusFilter').value='';pageNum=0;go('program')}
function statsHTML(){const n=completed(STUDY),logged=STUDY.reduce((a,d)=>a+seconds(d),0),review=STUDY.filter(d=>status(d)==='review').length;return [['Completed',`${n} / ${STUDY.length}`,`${pct(n,STUDY.length)}% of training`],['Focused time',`${Math.floor(logged/3600)}h ${Math.floor(logged%3600/60)}m`,'Recorded by timer'],['Needs review',review,'Revisit difficult topics'],['Study days left',STUDY.length-n,'At your own pace']].map(([l,v,s])=>`<div class="stat"><div class="label">${l}</div><strong>${v}</strong><small>${s}</small></div>`).join('')}
function render(){if(page==='today')renderToday();if(page==='program')renderProgram();if(page==='roadmap')renderRoadmap();if(page==='resources')renderResources();if(page==='progress')renderProgress();if(page==='partners')renderPartners()}
function renderToday(){const d=DAYS[selected],p=PHASES.find(p=>d.week>=p.start&&d.week<=p.end),n=completed(STUDY);$('hero').innerHTML=`<div class="hero"><div style="flex:1"><div class="eyebrow">Your one-year mission</div><h2>From PhD to AI interview-ready</h2><p>Research engineering · Applied science · Machine learning engineering</p>${bar(n,STUDY.length)}</div><div class="hero-stat"><strong>${pct(n,STUDY.length)}%</strong><small>${n} of ${STUDY.length} study sessions</small></div></div>`;$('stats').innerHTML=statsHTML();
const routines=d.type==='LeetCode'?[[3,'Read the prompt; clarify input and edge cases.'],[17,'Write a solution without help.'],[7,'Test and analyze time / space complexity.'],[3,'Record a mistake or explain the approach aloud.']]:d.type==='AI coding'?[[3,'Write the inputs, outputs and assumptions.'],[17,'Implement the core idea from scratch.'],[7,'Test a small example or compare with a library.'],[3,'Note the limitations or next step.']]:d.type==='Math / theory'?[[5,'Read the relevant concept in the linked resource.'],[15,'Derive a formula or solve a small example.'],[7,'Connect the concept to an ML application.'],[3,'Explain the result in your own words.']]:[[5,'Read the task and choose a realistic deliverable.'],[17,'Work on one experiment, paper section or interview answer.'],[5,'Check evidence, assumptions or trade-offs.'],[3,'Write down the result and next action.']];
const st=status(d);$('daily').innerHTML=`<div class="panel-head"><div><div class="eyebrow">Day ${selected+1} / 365 · Week ${d.week}</div><h2>${fmt(d.date,{weekday:'long',month:'short',day:'numeric'})}</h2></div><div class="datebar"><button class="btn icon" data-day="${selected-1}" ${selected===0?'disabled':''} aria-label="Previous day">‹</button><input id="datepick" type="date" min="${DAYS[0].date}" max="${DAYS.at(-1).date}" value="${d.date}" aria-label="Choose date"><button class="btn icon" data-day="${selected+1}" ${selected===364?'disabled':''} aria-label="Next day">›</button></div></div><div class="taskmeta">${chip(d)}<small>· ${esc(d.focus)} · ${d.minutes?d.minutes+' min maximum':'Rest day'}</small></div><h2 class="taskname">${esc(d.task)}</h2><p class="muted">${esc(p.name)}</p>${d.url?`<div class="linkrow"><a class="btn primary" href="${safeUrl(d.url)}" target="_blank" rel="noopener noreferrer">Open learning resource ↗</a>${d.type==='LeetCode'?'<a class="btn" href="https://leetcode.com/studyplan/top-interview-150/" target="_blank" rel="noopener">Practice catalog ↗</a>':d.type==='AI coding'?'<a class="btn" href="https://www.deep-ml.com/problems" target="_blank" rel="noopener">AI challenge library ↗</a>':''}</div>`:''}${d.minutes?`<div class="sectionline"></div><h3>How to use your 30 minutes</h3><div class="routine" style="margin-top:10px">${routines.map(([m,t])=>`<div class="routine-row"><b>${m} min</b><span>${t}</span></div>`).join('')}</div><div class="timerpanel"><div><div class="eyebrow">Focus timer</div><div id="clock" class="clock">30:00</div><small id="timerHint">Stops at 30 minutes</small></div><div class="timerbuttons"><button class="btn primary" id="startTimer">${timerId?'Pause':'Start'}</button></div></div><div class="sectionline"></div><h3>Session status</h3><div class="statusrow" style="margin-top:10px">${['not-started','in-progress','done','review'].map(s=>`<button class="btn sm ${st===s?'selected':''}" data-status="${s}" aria-pressed="${st===s}">${STATUS[s]}</button>`).join('')}</div>`:'<div class="sectionline"></div><p>Take the day off. If you choose to review, keep it within 30 minutes. Rest is part of the plan.</p>'}<div class="sectionline"></div><label for="notes"><strong>Learning journal</strong></label><textarea class="note" id="notes" placeholder="What did you learn? What mistake should you avoid next time?">${esc(entry(d).notes||'')}</textarea><small id="saveNote">${mode==='cloud'?'Private notes · queued for cloud sync':'Local demo · notes stay in this browser'}</small><div class="privateextra"><label for="solution"><strong>Code solution (private)</strong></label><textarea class="note solution" id="solution" maxlength="100000" placeholder="Paste your code or pseudocode…">${esc(entry(d).solution||'')}</textarea><label for="customTask"><strong>Personal challenge / next step (private)</strong></label><textarea class="note" id="customTask" maxlength="10000" placeholder="Optional alternative or follow-up; keep total study time within 30 min.">${esc(entry(d).custom_task||'')}</textarea></div>`;refreshClock();$('datepick').onchange=e=>{const i=DAYS.findIndex(d=>d.date===e.target.value);if(i>=0)selectDay(i)};$('notes').maxLength=100000;$('notes').oninput=e=>{update(d,{notes:e.target.value});$('saveNote').textContent=mode==='cloud'?'Queued for cloud sync — see status above.':'Saved locally.'};$('solution').oninput=e=>update(d,{solution:e.target.value});$('customTask').oninput=e=>update(d,{custom_task:e.target.value});if(d.minutes){$('startTimer').onclick=toggleTimer;}
const wd=DAYS.filter(x=>x.week===d.week),ws=wd.filter(x=>x.minutes);$('weekpanel').innerHTML=`<div class="panel-head"><div><div class="eyebrow">Week ${d.week} / 52</div><h2>${esc(d.focus)}</h2></div><button class="btn sm" data-week="${d.week}">View week</button></div><div class="weeklist">${wd.map(x=>`<button class="weekrow ${x.date===d.date?'current':''}" data-day="${DAYS.indexOf(x)}"><span class="daybadge">${x.day.slice(0,3)}<b>${Number(x.date.slice(-2))}</b></span><span class="taskshort"><strong>${esc(x.task)}</strong><small>${esc(x.type)} · ${x.minutes} min</small></span><span class="statusdot ${status(x)}" title="${STATUS[status(x)]}"></span></button>`).join('')}</div><div class="weekprogress">${bar(completed(ws),ws.length)}<small>${completed(ws)}/${ws.length}</small></div>`;$('phaseMini').innerHTML=PHASES.map((p,i)=>{const ds=STUDY.filter(d=>d.week>=p.start&&d.week<=p.end);return `<div class="phase-row"><span class="phase-num">0${i+1}</span><div><strong>${esc(p.name)}</strong><small>Weeks ${p.start}–${p.end}</small>${bar(completed(ds),ds.length)}</div><small>${pct(completed(ds),ds.length)}%</small></div>`}).join('')}
function refreshClock(){const d=DAYS[selected];if(!$('clock'))return;let remaining=d.minutes*60-seconds(d);if(timerId&&timerIndex===selected)remaining=clamp(Math.ceil((deadline-Date.now())/1000),0,d.minutes*60);$('clock').textContent=`${String(Math.floor(remaining/60)).padStart(2,'0')}:${String(remaining%60).padStart(2,'0')}`;$('startTimer').textContent=timerId&&timerIndex===selected?'Pause':remaining===0?'Finished':'Start';$('startTimer').disabled=remaining===0;$('timerHint').textContent=remaining===0?'Time is up. Record your progress.':timerId&&timerIndex===selected?'Focus session running':'Stops at 30 minutes'}
function pauseTimer(){if(timerId===null)return;const d=DAYS[timerIndex];update(d,{seconds:clamp(d.minutes*60-Math.ceil((deadline-Date.now())/1000),0,d.minutes*60)});clearInterval(timerId);timerId=null;timerIndex=null;refreshClock()}
function toggleTimer(){if(timerId!==null){pauseTimer();$('stats').innerHTML=statsHTML();return}const d=DAYS[selected];const rem=d.minutes*60-seconds(d);if(rem<=0)return;timerIndex=selected;deadline=Date.now()+rem*1000;if(status(d)==='not-started')update(d,{status:'in-progress'});timerId=setInterval(()=>{const left=Math.ceil((deadline-Date.now())/1000);if(left<=0){pauseTimer();render();notify('30 minutes complete. Stop and record your learning.');return}const x=DAYS[timerIndex];update(x,{seconds:clamp(x.minutes*60-left,0,x.minutes*60)});refreshClock()},1000);renderToday()}
function renderProgram(){const q=$('search').value.toLowerCase().trim(),type=$('typeFilter').value,w=$('weekFilter').value,s=$('statusFilter').value;const items=DAYS.filter(d=>(!q||`${d.task} ${d.date} ${d.focus} ${d.type} ${d.day}`.toLowerCase().includes(q))&&(!type||d.type===type)&&(!w||d.week===+w)&&(!s||status(d)===s));const size=21,max=Math.max(1,Math.ceil(items.length/size));pageNum=clamp(pageNum,0,max-1);const slice=items.slice(pageNum*size,(pageNum+1)*size);$('programResults').innerHTML=`<p class="muted" style="margin-bottom:9px">${items.length} matching days</p><div class="programtable"><table><thead><tr><th>Date</th><th>Session</th><th>Assignment</th><th>Time</th><th>Status</th><th>Link</th></tr></thead><tbody>${slice.map(d=>`<tr><td class="tabledate"><strong>${fmt(d.date,{month:'short',day:'numeric'})}</strong><small>${d.day.slice(0,3)} · W${d.week} · ${d.date.slice(0,4)}</small></td><td>${chip(d)}</td><td><button class="tasklink" data-day="${DAYS.indexOf(d)}">${esc(d.task)}</button><small>${esc(d.focus)}</small></td><td>${d.minutes} min</td><td><span class="statusdot ${status(d)}" style="display:inline-block;margin-right:5px"></span>${STATUS[status(d)]}</td><td>${d.url?`<a href="${safeUrl(d.url)}" target="_blank" rel="noopener noreferrer">Open ↗</a>`:'—'}</td></tr>`).join('')||'<tr><td colspan="6" class="empty">No matching assignments.</td></tr>'}</tbody></table></div><div class="pagination"><small>${items.length?pageNum*size+1:0}–${Math.min(items.length,(pageNum+1)*size)} of ${items.length}</small><div><button class="btn sm" data-pag="-1" ${pageNum===0?'disabled':''}>Previous</button><span class="btn sm" style="cursor:default">${pageNum+1} / ${max}</span><button class="btn sm" data-pag="1" ${pageNum>=max-1?'disabled':''}>Next</button></div></div>`}
function renderRoadmap(){$('roadmap').innerHTML=PHASES.map((p,i)=>`<section class="phase-section"><div class="phase-heading"><span class="phase-num">0${i+1}</span><div><h2>${esc(p.name)}</h2><p class="muted">Weeks ${p.start}–${p.end} · ${esc(p.desc)}</p></div></div><div class="milestonegrid">${WEEKS.filter(w=>w.week>=p.start&&w.week<=p.end).map(w=>{const ds=STUDY.filter(d=>d.week===w.week);return `<button class="milestone" data-week="${w.week}"><div class="eyebrow">Week ${w.week} · ${fmt(w.date,{month:'short',day:'numeric'})}</div><h3>${esc(w.focus)}</h3><small>${esc(w.goal)}</small>${bar(completed(ds),ds.length)}<small>${completed(ds)} / ${ds.length} completed · Open week →</small></button>`}).join('')}</div></section>`).join('')}
function category(r){if(r.url.includes('arxiv.org/abs/'))return 'Research papers';if(/leetcode|deep-ml|leetml|tensortonic/.test(r.url))return 'Practice platforms';if(/stanford|mml-book|statlearning|d2l|huggingface|fullstack|karpathy\/nn/.test(r.url))return 'Courses & textbooks';if(/interview-guide/.test(r.url))return 'Interview guides';if(/arxiv.org\/list/.test(r.url))return 'Research discovery';return 'Tools & documentation'}
function renderResources(){const q=$('resourceSearch').value.toLowerCase().trim(),cat=$('resourceType').value;const rr=RESOURCES.filter(r=>(!q||`${r.name} ${r.url}`.toLowerCase().includes(q))&&(!cat||category(r)===cat));$('resourceGrid').innerHTML=rr.map(r=>`<a class="resource-card" href="${safeUrl(r.url)}" target="_blank" rel="noopener noreferrer"><span class="eyebrow">${esc(category(r))}</span><strong>${esc(r.name)}</strong><span class="domain">${esc(new URL(r.url).hostname)}</span><span class="open">Open resource ↗</span></a>`).join('')||'<p class="muted">No matching resources.</p>'}
function renderProgress(){$('progressStats').innerHTML=statsHTML();$('skillBreakdown').innerHTML=TYPES.filter(t=>t!=='Rest').map(t=>{const ds=STUDY.filter(d=>d.type===t);return `<div class="skill-row"><div class="skill-head"><strong>${esc(t)}</strong><span>${completed(ds)} / ${ds.length}</span></div>${bar(completed(ds),ds.length)}</div>`}).join('');$('heatmap').innerHTML=DAYS.map((d,i)=>`<button class="${status(d)}" data-day="${i}" title="${esc(d.date+' · '+d.task+' · '+STATUS[status(d)])}" aria-label="${esc(d.date+' '+STATUS[status(d)])}"></button>`).join('');const review=STUDY.filter(d=>status(d)==='review');$('revisionQueue').innerHTML=review.length?review.map(d=>`<div class="sectionline" style="margin:12px 0"></div><button class="tasklink" data-day="${DAYS.indexOf(d)}">${esc(d.task)}</button><br><small>${d.date} · ${esc(d.type)}</small>`).join(''):'<p class="empty">Nothing flagged for review yet.</p>';const notes=DAYS.filter(d=>entry(d).notes?.trim()).reverse();$('journal').innerHTML=notes.length?notes.slice(0,12).map(d=>`<div class="sectionline" style="margin:12px 0"></div><button class="tasklink" data-day="${DAYS.indexOf(d)}">${esc(d.date+' · '+d.task)}</button><p style="white-space:pre-wrap;overflow-wrap:anywhere;margin-top:5px">${esc(entry(d).notes)}</p>`).join(''):'<p class="empty">Your notes will appear here after your first session.</p>'}
function download(name,text,type){const u=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=u;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),1000)}
function setTheme(){document.body.classList.toggle('dark',theme==='dark');$('theme').setAttribute('aria-pressed',theme==='dark');$('theme').title=theme==='dark'?'Switch to light mode':'Switch to dark mode'}
$('typeFilter').innerHTML+=[...TYPES].map(t=>`<option value="${esc(t)}">${esc(t)}</option>`).join('');$('weekFilter').innerHTML+=WEEKS.map(w=>`<option value="${w.week}">Week ${w.week} — ${esc(w.focus)}</option>`).join('');$('resourceType').innerHTML+=[...new Set(RESOURCES.map(category))].map(c=>`<option value="${esc(c)}">${esc(c)}</option>`).join('');for(const id of ['search','typeFilter','weekFilter','statusFilter'])$(id).addEventListener(id==='search'?'input':'change',()=>{pageNum=0;renderProgram()});for(const id of ['resourceSearch','resourceType'])$(id).addEventListener(id==='resourceSearch'?'input':'change',renderResources);$('clearFilters').onclick=()=>{for(const id of ['search','typeFilter','weekFilter','statusFilter'])$(id).value='';pageNum=0;renderProgram()};$('todayJump').onclick=today;$('theme').onclick=()=>{theme=theme==='dark'?'light':'dark';setTheme();save()};$('localdate').textContent=fmt(dateKey(),{weekday:'short',month:'short',day:'numeric',year:'numeric'});$('exportData').onclick=()=>{pauseTimer();download('AI_Academy_Progress.json',JSON.stringify({version:2,entries:data,theme},null,2),'application/json');notify('Backup exported')};$('exportCSV').onclick=()=>{pauseTimer();const quote=x=>{let v=String(x??'');if(/^[=+@\-\t\r\n]/.test(v))v="'"+v;return '"'+v.replaceAll('"','""')+'"'};download('AI_Academy_Progress.csv',[['Date','Week','Type','Assignment','Status','Minutes logged','Notes','Solution','Personal challenge','Resource'],...DAYS.map(d=>[d.date,d.week,d.type,d.task,STATUS[status(d)],(seconds(d)/60).toFixed(1),entry(d).notes||'',entry(d).solution||'',entry(d).custom_task||'',d.url])].map(r=>r.map(quote).join(',')).join('\r\n'),'text/csv;charset=utf-8');notify('CSV exported')};$('importData').onclick=()=>$('importFile').click();$('importFile').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;const j=JSON.parse(await f.text());if(![1,2].includes(j.version)||!j.entries||typeof j.entries!=='object'||Array.isArray(j.entries))throw Error('Invalid backup');let cleaned={};for(const d of DAYS){const a=j.entries[d.date];if(a&&typeof a==='object'){cleaned[d.date]={status:d.minutes&&['not-started','in-progress','done','review'].includes(a.status)?a.status:'not-started',seconds:Math.round(clamp(Number(a.seconds)||0,0,d.minutes*60)),notes:typeof a.notes==='string'?a.notes.slice(0,100000):'',solution:typeof a.solution==='string'?a.solution.slice(0,100000):'',custom_task:typeof a.custom_task==='string'?a.custom_task.slice(0,10000):''}}}if(!confirm('Replace current progress with this backup?'))return;pauseTimer();replaceEntries(cleaned);theme=j.theme==='dark'?'dark':'light';setTheme();save();render();notify('Backup imported')}catch(err){notify('Unable to import: invalid backup file')}finally{e.target.value=''}};$('resetData').onclick=()=>{if(confirm('Clear all progress, timer records and notes? Export a backup first if needed.')){pauseTimer();replaceEntries({});save();render();notify('Progress cleared or queued for sync')}};
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;if(b.dataset.page)go(b.dataset.page);else if(b.dataset.go)go(b.dataset.go);else if(b.dataset.day!==undefined)selectDay(+b.dataset.day);else if(b.dataset.week)chooseWeek(+b.dataset.week);else if(b.dataset.pag){pageNum+=+b.dataset.pag;renderProgram()}else if(b.dataset.status){const d=DAYS[selected];update(d,{status:b.dataset.status});if(b.dataset.status==='done')pauseTimer();renderToday();notify(STATUS[b.dataset.status])}});window.addEventListener('beforeunload',pauseTimer);setTheme();

// Collaborative edition — separate account-scoped, durable pending field patches.
let mode='locked', client=null, user=null, profile=null, pending={}, syncTimer=null, syncing=false, syncPromise=null, generation=0, cacheOK=true;
const fields=['status','seconds','notes','solution','custom_task'];
const blank=()=>({status:'not-started',seconds:0,notes:'',solution:'',custom_task:''});
const config=window.ACADEMY_CONFIG||{};
function gate(message,{login=false,demo=false,retry=false,signout=false}={}){document.body.classList.add('locked');$('authGate').hidden=false;$('authMessage').textContent=message;$('loginForm').hidden=!login;$('demoButton').hidden=!demo;$('authRetry').hidden=!retry;$('gateSignOut').hidden=!signout;}
function unlock(){document.body.classList.remove('locked');$('authGate').hidden=true;$('accountLabel').textContent=mode==='demo'?'Local demo':profile.display_name;$('signOut').hidden=mode!=='cloud';$('syncNow').hidden=mode!=='cloud';go('today');syncText(mode==='demo'?'Local demo — no cloud account or synchronization.':'Cloud connected');}
function syncText(t){$('syncStatus').textContent=t;}
function queueKey(){return 'academy-v2-pending:'+config.supabaseUrl+':'+user.id;}
function persistQueue(){if(!user)return;try{localStorage.setItem(queueKey(),JSON.stringify(pending));cacheOK=true;}catch(e){cacheOK=false;}}
function loadQueue(){try{const q=JSON.parse(localStorage.getItem(queueKey())||'{}');return q&&typeof q==='object'&&!Array.isArray(q)?q:{};}catch(e){cacheOK=false;return {};}}
function queuePatch(date,patch){if(!user)return;const q=pending[date]||{};for(const k of fields)if(Object.hasOwn(patch,k))q[k]=patch[k];pending[date]=q;persistQueue();syncText(cacheOK?'Changes pending cloud sync…':'Changes pending — browser storage unavailable; keep this page open.');scheduleSync();}
function scheduleSync(){if(syncTimer!==null)return;syncTimer=setTimeout(()=>{syncTimer=null;flushQueue();},2500);}
function replaceEntries(next){if(mode==='cloud'){for(const d of DAYS){if(data[d.date]||next[d.date])queuePatch(d.date,{...blank(),...next[d.date]});}}data=next;}
async function flushQueue(){if(mode!=='cloud'||!user)return false;if(syncing)return syncPromise;const g=generation;const uid=user.id;const snapshot=JSON.parse(JSON.stringify(pending));const items=Object.entries(snapshot);if(!items.length){syncText('All changes synced');return true;}syncing=true;syncText('Syncing to cloud…');syncPromise=(async()=>{try{for(const [date,patch] of items){if(g!==generation)return false;const {error}=await client.rpc('academy_patch_day',{p_user:uid,p_day:date,p_patch:patch});if(error)throw error;if(g!==generation||user?.id!==uid)return false;for(const k of Object.keys(patch)){if(pending[date]&&pending[date][k]===patch[k])delete pending[date][k];}if(pending[date]&&!Object.keys(pending[date]).length)delete pending[date];persistQueue();}if(Object.keys(pending).length){syncText('More changes pending…');scheduleSync();}else syncText('All changes synced · '+new Date().toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'}));return true;}catch(e){if(g===generation){syncText('Sync failed — '+(cacheOK?'changes queued on this browser.':'keep this page open and export a backup.')+' Retry when connected.');console.warn('Sync error',e.message);}return false;}finally{if(g===generation){syncing=false;syncPromise=null;}}})();return syncPromise;}
async function pull(){const g=generation;if(!user)return;const {data:rows,error}=await client.from('academy_progress').select('day,status,seconds,notes,solution,custom_task').eq('user_id',user.id);if(error)throw error;if(g!==generation)return;const next={};for(const r of rows){const {day,...rest}=r;next[day]=rest;}for(const [day,patch] of Object.entries(pending))next[day]={...next[day],...patch};data=next;}
async function syncAndRefresh(){if(mode!=='cloud')return;pauseTimer();const g=generation;const ok=await flushQueue();if(!ok||g!==generation)return;try{await pull();if(g!==generation)return;render();syncText('Cloud up to date · '+new Date().toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'}));}catch(e){syncText('Could not refresh cloud progress. Your displayed data is unchanged.');}}
function clearWorkspace(){generation++;if(syncTimer!==null)clearTimeout(syncTimer);syncTimer=null;if(timerId!==null)clearInterval(timerId);timerId=null;timerIndex=null;syncing=false;syncPromise=null;mode='locked';data={};pending={};user=null;profile=null;for(const id of ['daily','hero','stats','weekpanel','phaseMini','programResults','roadmap','progressStats','skillBreakdown','heatmap','revisionQueue','journal','partnerCards'])$(id).replaceChildren();}
async function enter(session){if(!session?.user){clearWorkspace();gate('Sign in with your assigned email and password.',{login:true});return;}if(mode==='cloud'&&user?.id===session.user.id)return;clearWorkspace();const g=generation;user=session.user;gate('Checking membership and loading your progress…',{signout:true});try{const {data:p,error}=await client.from('academy_profiles').select('display_name,share_progress').eq('user_id',user.id).maybeSingle();if(error)throw error;if(g!==generation)return;if(!p){gate('This account is not authorized for the academy. Ask the administrator to add your profile.',{signout:true});return;}profile=p;pending=loadQueue();await pull();if(g!==generation)return;mode='cloud';unlock();if(Object.keys(pending).length){syncText('Recovering unsynced changes…');scheduleSync();}}catch(e){if(g===generation)gate('Could not load your account: '+e.message,{retry:true,signout:true});}}
async function signOut(){if(mode==='cloud'){pauseTimer();const ok=await flushQueue();if(!ok||Object.keys(pending).length){notify('Unsynced changes remain. Sync or export a backup before signing out.');return;}}try{const {error}=await client.auth.signOut({scope:'local'});if(error)throw error;clearWorkspace();gate('Signed out. Sign in to continue.',{login:true});}catch(e){notify('Sign-out failed: '+e.message);$('authMessage').textContent='Sign-out failed: '+e.message;}}
async function renderPartners(){const g=generation;$('shareProgress').disabled=mode!=='cloud';$('shareProgress').checked=!!profile?.share_progress;$('shareMessage').textContent='';if(mode!=='cloud'){$('partnerCards').innerHTML='<article class="panel"><h3>Local demo</h3><p class="muted">Configure Supabase and sign in to see actual partner progress.</p></article>';return;}$('partnerCards').textContent='Loading shared statistics…';const {data:rows,error}=await client.rpc('academy_partner_stats');if(g!==generation||page!=='partners')return;if(error){$('partnerCards').textContent='Unable to load shared statistics: '+error.message;return;}$('partnerCards').innerHTML=rows.map(r=>`<article class="panel"><div class="eyebrow">${r.is_me?'Your account':'Study partner'}</div><h2>${esc(r.display_name)}</h2>${r.completed===null?'<p class="muted">This person has not enabled progress sharing.</p>':`<div class="partnerstat">${pct(r.completed,STUDY.length)}%</div>${bar(r.completed,STUDY.length)}<p>${r.completed} / ${STUDY.length} completed · ${Math.floor(r.total_seconds/60)} min studied</p><strong>This week: ${r.week_completed} completed</strong>`}</article>`).join('');}
$('shareProgress').onchange=async()=>{if(mode!=='cloud')return;const g=generation;const val=$('shareProgress').checked;$('shareProgress').disabled=true;const {error}=await client.from('academy_profiles').update({share_progress:val}).eq('user_id',user.id);if(g!==generation)return;if(error){$('shareProgress').checked=!!profile.share_progress;$('shareMessage').textContent='Could not save sharing preference.';$('shareProgress').disabled=false;}else{profile.share_progress=val;await renderPartners();$('shareMessage').textContent=val?'Sharing enabled.':'Sharing disabled.';}};
$('refreshPartners').onclick=renderPartners;$('syncNow').onclick=syncAndRefresh;$('signOut').onclick=signOut;$('gateSignOut').onclick=signOut;
$('authRetry').onclick=async()=>{if(!client){location.reload();return;}const {data:s,error}=await client.auth.getSession();if(error)gate(error.message,{retry:true});else await enter(s.session);};
$('demoButton').onclick=()=>{mode='demo';try{const s=JSON.parse(localStorage.getItem(KEY)||'{}');data=s.entries||{};}catch(e){data={};}unlock();};
$('loginForm').onsubmit=async e=>{e.preventDefault();if(!client)return;$('loginButton').disabled=true;$('authMessage').textContent='Signing in…';try{const {data:s,error}=await client.auth.signInWithPassword({email:$('email').value.trim(),password:$('password').value});if(error)throw error;$('password').value='';await enter(s.session);}catch(e){$('authMessage').textContent='Sign-in failed: '+e.message;}finally{$('loginButton').disabled=false;}};
window.addEventListener('online',()=>{if(mode==='cloud')flushQueue();});
window.addEventListener('focus',()=>{if(mode==='cloud'&&Object.keys(pending).length)flushQueue();});
window.addEventListener('beforeunload',e=>{if(mode==='cloud'&&Object.keys(pending).length&&!cacheOK){e.preventDefault();e.returnValue='';}});
function isPublicKey(k){if(k.startsWith('sb_publishable_'))return true;try{return JSON.parse(atob(k.split('.')[1].replace(/-/g,'+').replace(/_/g,'/'))).role==='anon';}catch(e){return false;}}
(async()=>{if(!config.supabaseUrl||!config.supabasePublishableKey){gate('Cloud is not configured yet. Follow README.md to connect your Supabase project, or explore a separate local demo.',{demo:true});return;}if(!window.supabase){gate('Authentication library unavailable. Check your internet connection and reload.',{retry:true});return;}try{if(!/^https:\/\//.test(config.supabaseUrl)||!isPublicKey(config.supabasePublishableKey))throw Error('Use HTTPS and a public publishable key only.');client=window.supabase.createClient(config.supabaseUrl,config.supabasePublishableKey,{auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:false}});client.auth.onAuthStateChange((event,s)=>{if(event==='SIGNED_OUT')setTimeout(()=>{clearWorkspace();gate('Signed out. Sign in to continue.',{login:true});},0);else if(event==='SIGNED_IN'&&mode==='cloud'&&user?.id!==s?.user?.id)setTimeout(()=>enter(s),0);});const {data:s,error}=await client.auth.getSession();if(error)throw error;await enter(s.session);}catch(e){gate('Configuration or connection error: '+e.message,{retry:true});}})();
